def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Rays are traced from each original marker. Each route entry is (r,c,value).
    routes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                routes.append((r, c, [(r, c + 1, 5), (r, c + 2, 5), (r - 1, c + 2, 1)]))
            elif color == 2:
                routes.append((r, c, [(r, c - d, 2 if d == 4 else 5) for d in range(1, 5)]))
            elif color == 3:
                routes.append((r, c, [(r + d, c, 3 if d == 3 else 5) for d in range(1, 4)]))
            elif color == 6:
                routes.append((r, c, [(r - d, c, 6 if d == 6 else 5) for d in range(1, 7)]))

    visits = {}
    values = {}
    for r, c, route in routes:
        source = (r, c)
        for rr, cc, value in route:
            if 0 <= rr < h and 0 <= cc < w:
                visits.setdefault((rr, cc), set()).add(source)
                values[(rr, cc)] = value

    crossings = []
    for (r, c), sources in visits.items():
        if len(sources) > 1:
            out[r][c] = 4
            crossings.append((r, c))
        else:
            out[r][c] = values[(r, c)]

    # Every crossing launches a diagonal 4-ray down-left to the grid edge.
    for r, c in crossings:
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
